public boolean syncNote(Context context, long noteId) {
    if (noteId <= 0) {
        throw new IllegalArgumentException("Wrong note id:" + noteId);
    }
    if (!isLocalModified()) {
        return true;
    }
    if (context.getContentResolver().update(ContentUris.withAppendedId(Notes.CONTENT_NOTE_URI, noteId), this.mNoteDiffValues, null, null) == 0) {
        Log.e(TAG, "Update note error, should not happen");
    }
    this.mNoteDiffValues.clear();
    return (this.mNoteData.isLocalModified() && this.mNoteData.pushIntoContentResolver(context, noteId) == null) ? false : true;
}
